// ============================================================================
// VERIROUTE AI - STAGE 3: HYBRID RRF + JINA RERANKER + BOUNDARY ENGINE
// Mode: Run Once for Each Item
// ============================================================================

// 1. Pull Upstream Data Safely
const queryData = $('Limit').item.json;
const qdrantResponse = $('HTTP Req - Qdrant Hybrid Search').item.json;
const jinaResponse = $('HTTP Req - Jina Reranker').item.json;

const tid = String(queryData.ticket_id || "").trim();

const points = (qdrantResponse && qdrantResponse.result && Array.isArray(qdrantResponse.result.points))
  ? qdrantResponse.result.points
  : [];

const jinaResults = (jinaResponse && Array.isArray(jinaResponse.results))
  ? jinaResponse.results
  : [];

// 2. Helper Functions for Metadata & Document Code Extraction
function getDocId(payload) {
  if (!payload) return "UNKNOWN_DOC";
  return payload.doc_id || payload.document_id || payload.id || payload.code || payload.file_name || "UNKNOWN_DOC";
}

function getChunkId(payload, pointId) {
  if (!payload) return String(pointId || "UNKNOWN_CHUNK");
  return payload.chunk_id || payload.chunk_index || String(pointId || "UNKNOWN_CHUNK");
}

function getTitle(payload, docId) {
  if (!payload) return docId;
  return payload.title || payload.section_title || payload.heading || payload.document_title || docId;
}

function getText(payload) {
  if (!payload) return "";
  return payload.text || payload.content || payload.page_content || payload.chunk_text || "";
}

function getBaseCode(docId) {
  if (!docId || typeof docId !== "string") return "UNKNOWN";
  const parts = docId.split("_");
  return parts.length >= 2 ? `${parts[0]}_${parts[1]}` : docId;
}

// 3. Map Stage 1 (Qdrant RRF) Candidates
const s1Candidates = points.map((pt, idx) => {
  const payload = pt.payload || {};
  const docId = getDocId(payload);
  return {
    s1_rank: idx + 1,
    point_id: pt.id,
    doc_id: docId,
    base_code: getBaseCode(docId),
    chunk_id: getChunkId(payload, pt.id),
    title: getTitle(payload, docId),
    text: getText(payload),
    s1_score: typeof pt.score === "number" ? Number(pt.score.toFixed(4)) : 0
  };
});

const s1Top1 = s1Candidates[0] || {
  doc_id: "NONE",
  base_code: "NONE",
  chunk_id: "NONE",
  title: "No Stage 1 Candidate",
  text: "",
  s1_score: 0
};

// 4. Map Stage 2 (Jina Cross-Encoder Reranker) Candidates
const s2Candidates = jinaResults.map((jr, idx) => {
  const originalIdx = typeof jr.index === "number" ? jr.index : idx;
  const orig = s1Candidates[originalIdx] || s1Top1;
  const jinaScore = typeof jr.relevance_score === "number" ? Number(jr.relevance_score.toFixed(4)) : 0;
  return {
    s2_rank: idx + 1,
    original_s1_rank: orig.s1_rank || (originalIdx + 1),
    doc_id: orig.doc_id,
    base_code: orig.base_code,
    chunk_id: orig.chunk_id,
    title: orig.title,
    text: orig.text,
    s1_score: orig.s1_score,
    jina_score: jinaScore
  };
});

const s2Top1 = s2Candidates[0] || {
  doc_id: s1Top1.doc_id,
  base_code: s1Top1.base_code,
  chunk_id: s1Top1.chunk_id,
  title: s1Top1.title,
  text: s1Top1.text,
  s1_score: s1Top1.s1_score,
  jina_score: 0
};

// Calculate Base 80/20 Residual Blended Score
const jinaTop1Score = s2Top1.jina_score || 0;
const s1Top1Score = s1Top1.s1_score || 0;
let blendedScore = Number(((0.80 * jinaTop1Score) + (0.20 * s1Top1Score)).toFixed(4));

// ============================================================================
// 5. FAULT INJECTION HOOKS (Exact Ticket IDs & Boundary Overrides)
// ============================================================================
if (tid === "FI-06-02199" || tid === "FI-06B") {
  blendedScore = 0.2199; // Boundary: Just below 0.2200 -> Tier 3
} else if (tid === "FI-06-02200" || tid === "FI-06A") {
  blendedScore = 0.2200; // Boundary: Exact lower boundary 0.2200 -> Tier 2
} else if (tid === "FI-05-04499" || tid === "FI-05B") {
  blendedScore = 0.4499; // Boundary: Just below 0.4500 -> Tier 2
} else if (tid === "FI-05-04500" || tid === "FI-05A") {
  blendedScore = 0.4500; // Boundary: Exact upper boundary 0.4500 -> Tier 1
} else if (tid === "FI-07-NAN" || tid === "FI-07A") {
  blendedScore = NaN;    // Corrupted score -> Triggers Fallback
} else if (tid === "FI-08-EXPIRED" || tid === "FI-08") {
  blendedScore = 0.8500; // High score -> Tier 1 Verifier evaluates the expired text
}

// ============================================================================
// 6. Explicit Half-Open Interval Boundary Routing
// Tier 1: [0.4500, 1.0000]
// Tier 2: [0.2200, 0.4500)
// Tier 3: [0.0000, 0.2200)
// Fallback: NaN, null, < 0, or empty candidates
// ============================================================================
const TIER1_THRESHOLD = 0.4500;
const TIER2_THRESHOLD = 0.2200;

let routingTier = "Fallback: Unroutable / No Candidates";
let boundaryInterval = "FALLBACK_INVALID_OR_EMPTY";

const hasValidCandidates = (s1Candidates.length > 0 && s2Candidates.length > 0 && s2Top1.doc_id !== "NONE");

if (hasValidCandidates && typeof blendedScore === "number" && !Number.isNaN(blendedScore) && blendedScore >= 0) {
  if (blendedScore >= TIER1_THRESHOLD) {
    routingTier = "Tier 1: Auto-Resolve";
    boundaryInterval = "[0.4500, 1.0000]";
  } else if (blendedScore >= TIER2_THRESHOLD) {
    routingTier = "Tier 2: Agent Assist / Copilot";
    boundaryInterval = "[0.2200, 0.4500)";
  } else {
    routingTier = "Tier 3: Escalate to Human";
    boundaryInterval = "[0.0000, 0.2200)";
  }
}

// Fault Injection Hook: Force Unrecognized Tier String to test Fallback Dead-Letter
if (tid === "FI-07-NULL" || tid === "FI-07B") {
  routingTier = "UNROUTABLE_NULL_TIER";
  boundaryInterval = "FALLBACK_CORRUPTED_TIER_STRING";
}

// 7. Build Formatted Summaries & Context Blocks
const s2Top5Formatted = s2Candidates.slice(0, 5).map(c =>
  `#${c.s2_rank} [Jina: ${c.jina_score} | RRF: ${c.s1_score}] ${c.doc_id} (${c.title})`
).join("\n");

const distinctDocs = [];
const seenBaseCodes = new Set();
for (const cand of s2Candidates) {
  if (!seenBaseCodes.has(cand.base_code)) {
    seenBaseCodes.add(cand.base_code);
    distinctDocs.push(cand);
  }
  if (distinctDocs.length >= 3) break;
}

const s2Top3DistinctFormatted = distinctDocs.map((c, i) =>
  `Option ${i + 1}: ${c.doc_id} (${c.title}) — Score: ${c.jina_score}`
).join("\n");

const s2Top3FullTextBlock = distinctDocs.map((c, i) =>
  `=== CANDIDATE DOCUMENT ${i + 1}: ${c.doc_id} (${c.title}) [Jina Score: ${c.jina_score}] ===\n${c.text}`
).join("\n\n");

// Inject Expired 2024 Header for Temporal Check on FI-08
const s2Top1FullText = (tid === "FI-08-EXPIRED" || tid === "FI-08")
  ? `[POLICY METADATA: EFFECTIVE 2023-01-01 | EXPIRED 2024-12-31 — SUPERSEDED AND INACTIVE IN 2026]\n` + (s2Top1.text || "")
  : (s2Top1.text || "");

// 8. Return Full Payload for Switch & Downstream Nodes
return {
  json: {
    ticket_id: tid || "UNKNOWN_TICKET",
    customer_query: queryData.customer_query || "",
    query_type: queryData.query_type || "",
    category: queryData.category || "",
    expected_policy_id: queryData.primary_expected_doc_id || queryData.primary_doc_code || "",
    s1_top_1_id: s1Top1.doc_id,
    s1_top_1_score: s1Top1.s1_score,
    s2_top_1_id: s2Top1.doc_id,
    s2_top_1_title: s2Top1.title,
    s2_top_1_jina_score: jinaTop1Score,
    blended_score: Number.isNaN(blendedScore) ? "NaN" : blendedScore,
    routing_tier: routingTier,
    boundary_interval: boundaryInterval,
    s2_top_1_full_text: s2Top1FullText,
    s2_top_5_reranked: s2Top5Formatted,
    s2_top_3_distinct_codes: s2Top3DistinctFormatted,
    s2_top_3_full_text_block: s2Top3FullTextBlock
  }
};

