// ============================================================================
// VERIROUTE AI - STAGE 3: UNIFIED TELEMETRY, FAIL-CLOSED GUARD & PACKAGING
// Mode: Run Once for Each Item
// ============================================================================

const currentInput = $input.item.json;
const base = $('Code - Hybrid RRF Summary').item.json;
const tid = String(base.ticket_id || "").trim();
const initialTier = base.routing_tier || "Fallback: Unroutable / No Candidates";

// 1. Helper: Fail-Closed Tier 1 Verifier Parser (Supports both schema formats)
function parseVerifierResponse(rawVerifierJson) {
  if (!rawVerifierJson || rawVerifierJson.error) {
    const errMsg =
      rawVerifierJson?.error?.message ||
      rawVerifierJson?.error ||
      "HTTP timeout or network error on Verifier";
    return {
      passed: false,
      status: "VERIFIER_TIMEOUT_OR_API_ERROR_HOLD_TIER2",
      violation: "VERIFIER_API_OR_TIMEOUT_ERROR",
      explanation: `Fail-closed hold triggered: ${String(errMsg).slice(0, 160)}`
    };
  }

  let rawContent = "";
  if (
    rawVerifierJson.choices &&
    Array.isArray(rawVerifierJson.choices) &&
    rawVerifierJson.choices[0]?.message?.content
  ) {
    rawContent = String(rawVerifierJson.choices[0].message.content).trim();
  } else if (
    typeof rawVerifierJson.verification_passed === "boolean" ||
    typeof rawVerifierJson.verdict === "string"
  ) {
    rawContent = JSON.stringify(rawVerifierJson);
  } else {
    return {
      passed: false,
      status: "VERIFIER_EMPTY_RESPONSE_HOLD_TIER2",
      violation: "EMPTY_OR_UNRECOGNIZED_PAYLOAD",
      explanation: "Verifier returned empty or unrecognized structure; holding for Tier 2 review."
    };
  }

  // Strip optional markdown code fences safely before strict JSON.parse
  const cleaned = rawContent
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  try {
    const parsed = JSON.parse(cleaned);
    if (parsed === null || typeof parsed !== "object") {
      return {
        passed: false,
        status: "VERIFIER_INVALID_OBJECT_HOLD_TIER2",
        violation: "INVALID_JSON_OBJECT",
        explanation: "Verifier JSON was not a valid object; held for Tier 2."
      };
    }

    // Normalize violation / failure reason across both prompt schemas
    const violationVal = String(
      parsed.violation_type || parsed.failure_reason || "NONE"
    ).trim();

    // Normalize explanation / audit notes across both prompt schemas
    const explanationVal = String(
      parsed.auditor_explanation || parsed.audit_notes || ""
    ).trim();

    // Check strict pass condition (accepts boolean verification_passed === true OR string verdict === "PASS")
    const hasBooleanPass = parsed.verification_passed === true;
    const hasStringPass = false; // strict boolean-only pass contract

    const isNoViolation =
      violationVal.toUpperCase() === "NONE" || violationVal === "";

    const isStrictPass = (hasBooleanPass || hasStringPass) && isNoViolation;

    if (isStrictPass) {
      return {
        passed: true,
        status: "VERIFIED_AUTO_SENT",
        violation: "NONE",
        explanation:
          explanationVal || "Verified 100% grounded and temporally active."
      };
    } else {
      return {
        passed: false,
        status: "VERIFIER_REJECTED_HOLD_TIER2",
        violation:
          violationVal !== "NONE" && violationVal !== ""
            ? violationVal
            : "POLICY_OR_GROUNDING_FAILURE",
        explanation:
          explanationVal || "Verifier flagged draft; downgraded to Tier 2."
      };
    }
  } catch (parseErr) {
    return {
      passed: false,
      status: "VERIFIER_MALFORMED_JSON_HOLD_TIER2",
      violation: "MALFORMED_VERIFIER_JSON",
      explanation:
        "Verifier returned non-JSON text (substring bypass blocked); held for Tier 2."
    };
  }
}

// 2. Determine Execution Path & Extract Draft / Verifier Status
let finalOperationalAction = "";
let auditVerdict = "";
let finalGeneratedOutput = "";
let destinationQueue = "";
let slaTarget = "";
let estHandlingCostUsd = 0;
let hopCount = 0;

if (initialTier === "Tier 1: Auto-Resolve") {
  // Retrieve Tier 1 Customer Draft (supports both node naming conventions)
  let draftText = "";
  try {
    const draftNodeJson = $('Tier 1 Customer Draft').item.json;
    draftText =
      draftNodeJson?.choices?.[0]?.message?.content ||
      "[Tier 1 Customer Draft Unavailable]";
  } catch (e1) {
    try {
      const draftNodeJson = $('HTTP Req - Tier 1 Customer Draft').item.json;
      draftText =
        draftNodeJson?.choices?.[0]?.message?.content ||
        "[Tier 1 Customer Draft Unavailable]";
    } catch (e2) {
      draftText = "[Tier 1 Customer Draft Error]";
    }
  }

  // Retrieve Tier 1 Verifier Response (supports both node naming conventions)
  let verifierNodeJson = null;
  try {
    verifierNodeJson = $('Tier 1 Verifier').item.json;
  } catch (e1) {
    try {
      verifierNodeJson = $('HTTP Req - Tier 1 Verifier').item.json;
    } catch (e2) {
      verifierNodeJson = { error: { message: "Verifier node execution failed" } };
    }
  }

  // ============================================================================
  // [FAULT INJECTION HOOKS: FI-01, FI-02, FI-03, FI-04, FI-08-EXPIRED]
  // Injects exact simulated Verifier failures when ticket_id matches
  // ============================================================================
  if (tid === "FI-01") {
    verifierNodeJson = {
      error: {
        message: "Simulated 1ms ETIMEDOUT timeout on Tier 1 Verifier"
      }
    };
  } else if (tid === "FI-02") {
    verifierNodeJson = {
      choices: [
        {
          message: {
            content:
              "Sure! The customer draft looks accurate and polite. Approved! (Non-JSON response)"
          }
        }
      ]
    };
  } else if (tid === "FI-03") {
    verifierNodeJson = {
      choices: [
        {
          message: {
            content:
              'Auditor review note: "verification_passed": true appears as a substring here, but this is NOT valid JSON and must be blocked!'
          }
        }
      ]
    };
  } else if (tid === "FI-04") {
    verifierNodeJson = {
      error: {
        message:
          "Request failed with status code 500 (Simulated OpenRouter Bad Endpoint)"
      }
    };
  } else if (tid === "FI-08" || tid === "FI-08-EXPIRED") {
    verifierNodeJson = {
      choices: [
        {
          message: {
            content: JSON.stringify({
              verification_passed: false,
              violation_type: "EXPIRED_OR_INACTIVE_POLICY",
              auditor_explanation:
                "Temporal validity check failed (As of 2026-11-09): Referenced promo/policy expired on 2024-12-31."
            })
          }
        }
      ]
    };
  }

  const vResult = parseVerifierResponse(verifierNodeJson);

  if (vResult.passed) {
    // Path A: Tier 1 Verified & Auto-Sent (0 Downgrade Hops)
    hopCount = 0;
    destinationQueue = "AUTO_DISPATCHED_CUSTOMER";
    slaTarget = "< 5 sec (Instant Auto-Reply)";
    estHandlingCostUsd = 0.003;
    finalOperationalAction = `Tier 1: Auto-Sent to Customer [Queue: ${destinationQueue} | SLA: ${slaTarget} | Hops: ${hopCount} | Cost: $${estHandlingCostUsd.toFixed(3)}]`;
    auditVerdict = `PASS (${vResult.status}): ${vResult.explanation}`;
    finalGeneratedOutput = draftText;
  } else {
    // Path B: Tier 1 Failed Verification -> Single-Hop Downgrade to Tier 2 Copilot
    hopCount = 1; // Maximum 1 automated hop (prevents cascading ping-pong)
    destinationQueue = "TIER2_COPILOT_REVIEW_QUEUE";
    slaTarget = "< 15 min (Agent Copilot Review)";
    estHandlingCostUsd = 1.50;

    let copilotNote = "";
    const currentNodeText = currentInput?.choices?.[0]?.message?.content || "";
    if (
      currentNodeText &&
      currentNodeText !== draftText &&
      !currentNodeText.includes('"verification_passed"') &&
      !currentNodeText.includes('"verdict"')
    ) {
      copilotNote = `\n\n--- TIER 2 AGENT COPILOT BRIEF ---\n${currentNodeText}`;
    }

    finalOperationalAction = `Downgraded Tier 1 -> Tier 2 Hold (Hops: ${hopCount}/1) [Queue: ${destinationQueue} | SLA: ${slaTarget} | Cost: $${estHandlingCostUsd.toFixed(2)}]`;
    auditVerdict = `HOLD_FOR_HUMAN (${vResult.status} | ${vResult.violation}): ${vResult.explanation}`;
    finalGeneratedOutput = `[HELD FOR TIER 2 AGENT REVIEW — NOT SENT TO CUSTOMER]\n\n--- HELD TIER 1 DRAFT ---\n${draftText}${copilotNote}`;
  }
} else if (initialTier === "Tier 2: Agent Assist / Copilot") {
  // Path C: Native Tier 2 Copilot Route
  hopCount = 0;
  destinationQueue = "TIER2_COPILOT_REVIEW_QUEUE";
  slaTarget = "< 15 min (Agent Copilot Review)";
  estHandlingCostUsd = 1.50;
  const copilotOutput =
    currentInput?.choices?.[0]?.message?.content ||
    "[Tier 2 Copilot Output Unavailable]";

  finalOperationalAction = `Tier 2: Routed to Agent Copilot [Queue: ${destinationQueue} | SLA: ${slaTarget} | Hops: ${hopCount} | Cost: $${estHandlingCostUsd.toFixed(2)}]`;
  auditVerdict = `N/A — Native Tier 2 Route (Interval: ${base.boundary_interval || "[0.2200, 0.4500)"})`;
  finalGeneratedOutput = copilotOutput;
} else if (
  initialTier === "Tier 3: Escalate to Human" ||
  initialTier === "Tier 3: Human Escalation"
) {
  // Path D: Native Tier 3 Human Escalation Route
  hopCount = 0;
  destinationQueue = "TIER3_SENIOR_ESCALATION_QUEUE";
  slaTarget = "< 2 hours (Senior Specialist)";
  estHandlingCostUsd = 6.00;

  finalOperationalAction = `Tier 3: Escalated to Human Specialist [Queue: ${destinationQueue} | SLA: ${slaTarget} | Hops: ${hopCount} | Cost: $${estHandlingCostUsd.toFixed(2)}]`;
  auditVerdict = `TIER3_LOW_CONFIDENCE_ESCALATION (Score ${base.blended_score} in ${base.boundary_interval || "[0.0000, 0.2200)"})`;
  finalGeneratedOutput =
    `[ESCALATED TO ${destinationQueue} — NO AI DRAFT SENT]\n` +
    `Blended Score: ${base.blended_score} (Threshold < 0.2200)\n` +
    `Top Candidate Snippets for Triage:\n${base.s2_top_3_distinct_codes || base.s2_top_5_reranked}`;
} else {
  // Path E: Switch Fallback Output ("Give Up Loudly" Dead-Letter Guard — FI-07-NAN / FI-07-NULL)
  hopCount = 0;
  destinationQueue = "TIER3_SENIOR_ESCALATION_QUEUE";
  slaTarget = "< 30 min (Fallback Dead-Letter Pager)";
  estHandlingCostUsd = 6.00;

  finalOperationalAction = `FALLBACK ESCALATION: Unroutable/Corrupted Tier [Queue: ${destinationQueue} | SLA: ${slaTarget} | Cost: $${estHandlingCostUsd.toFixed(2)}]`;
  auditVerdict = `FALLBACK_GIVE_UP_LOUDLY (Invalid routing_tier: "${initialTier}")`;
  finalGeneratedOutput =
    `[DEAD-LETTER FALLBACK ALERT -> ${destinationQueue}]\n` +
    `Ticket failed normal tier routing (routing_tier="${initialTier}", blended_score=${base.blended_score}). Assigned to Senior Queue.`;
}

// 3. Return Exact 12 Schema Columns for Upsert row(s) & Google Sheet WebApp
return {
  json: {
    ticket_id: tid || "UNKNOWN_TICKET",
    customer_query: String(base.customer_query || ""),
    expected_policy_id: String(base.expected_policy_id || ""),
    s1_top_1_id: String(base.s1_top_1_id || "NONE"),
    s2_top_1_id: String(base.s2_top_1_id || "NONE"),
    s2_top_1_title: String(base.s2_top_1_title || ""),
    blended_score: Number.isNaN(base.blended_score)
      ? "NaN"
      : Number(base.blended_score ?? 0),
    routing_tier: String(initialTier),
    final_operational_action: finalOperationalAction,
    audit_verdict: auditVerdict,
    final_generated_output: finalGeneratedOutput,
    timestamp: new Date().toISOString()
  }
};

